import RNA, random, multiprocessing as mp
target='....((((((((....((..(...................)..(((...((....))...((....))........))).......))))))))))....'
tp=set()
st=[]
for i,c in enumerate(target):
  if c=='(':st.append(i)
  elif c==')':tp.add((st.pop(),i))

def score(seq):
  fc=RNA.fold_compound(seq)
  mfe=fc.mfe()[0]
  mp=set()
  st=[]
  for i,c in enumerate(mfe):
    if c=='(':st.append(i)
    elif c==')':mp.add((st.pop(),i))
  return len(tp-mp)+len(mp-tp), mfe

def run(seed):
  random.seed(seed)
  best='AAAAGCGCGCGCAAAAGGAAGAAAAAAAAAAAAAAAAAAAUAAAACAAAGCGAAAGCAAAGCGAAAGCAAAAAAAACGGAAAAAAAUGGCGCGCGCAAAA'
  bd,_=score(best)
  for it in range(8000):
    cur=list(best)
    k=random.choice([1,1,2,2,3])
    if random.random()<0.75:
      pos=random.sample(range(12,88),k)
    else:
      pos=random.sample(range(100),k)
    for p in pos:
      cur[p]=random.choice('ACGU')
    nseq=''.join(cur)
    nd,_=score(nseq)
    if nd<=bd:
      best=nseq;bd=nd
    if nd==0:
      return (0,best)
  return (bd,best)

if __name__=='__main__':
  with mp.Pool(8) as p:
    res=p.map(run,range(16))
  res.sort()
  print('BEST',res[0])
  for d,s in res[:3]: print(d,s)
